const input = $json || {};

const sampleNotificationOutput = {
  success: true,
  result: {
    channelPayloads: {
      chatgpt: [
        {
          notificationId: 'ntf_chatgpt_1',
          title: 'International Social Mixer',
          message: 'Must Go · 88/100\nStrong social fit and easy to attend alone.',
          type: 'recommendation'
        }
      ],
      telegram: [
        {
          notificationId: 'ntf_telegram_1',
          chatId: '1938141471',
          text: '*Add International Social Mixer to calendar*\n\nApprove this action?',
          parseMode: 'Markdown',
          buttons: [
            { label: 'Approve', value: 'approve:social-1-calendar-2' },
            { label: 'Reject', value: 'reject:social-1-calendar-2' },
            { label: 'Alternative', value: 'alternative:social-1-calendar-2' }
          ],
          scheduledFor: null,
          type: 'approval_request',
          approvalId: 'apr_sample_123',
          relatedActionId: 'social-1-calendar-2'
        }
      ],
      whatsapp: [
        {
          notificationId: 'ntf_whatsapp_1',
          to: '+971500000000',
          text: 'Boxing starts in 60 minutes.',
          scheduledFor: null,
          type: 'reminder',
          relatedActionId: 'fitness-1-reminder'
        }
      ]
    }
  }
};

return [{
  json: {
    request: input.request || {
      channel: 'manual_test',
      userId: 'savas',
      telegramChatId: '1938141471',
      whatsappNumber: '+971500000000'
    },
    notificationEngineOutput:
      input.notificationEngineOutput ||
      (
        input.result?.channelPayloads
          ? input
          : sampleNotificationOutput
      ),
    metadata: input.metadata || {
      correlationId: `dispatcher-${Date.now()}`,
      testMode: true,
      dispatchEnabled: false
    }
  }
}];

const input = $json || {};
const notificationOutput = input.notificationEngineOutput || {};
const payloads = notificationOutput.result?.channelPayloads || {};
const request = input.request || {};
const metadata = input.metadata || {};

const chatgpt = Array.isArray(payloads.chatgpt) ? payloads.chatgpt : [];
const telegram = Array.isArray(payloads.telegram) ? payloads.telegram : [];
const whatsapp = Array.isArray(payloads.whatsapp) ? payloads.whatsapp : [];

const dispatchEnabled = metadata.dispatchEnabled === true;
const rejected = [];
const dispatchQueue = [];

const pushQueue = (channel, item, destination, status, reason = '') => {
  dispatchQueue.push({
    dispatchId: `dsp_${Date.now()}_${dispatchQueue.length + 1}`,
    channel,
    destination,
    notificationId: item.notificationId || null,
    type: item.type || 'notification',
    payload: item,
    status,
    reason,
    createdAt: new Date().toISOString()
  });
};

for (const item of chatgpt) {
  if (!item?.message) {
    rejected.push({ channel: 'chatgpt', item, reason: 'missing_message' });
    continue;
  }

  pushQueue(
    'chatgpt',
    item,
    request.conversationId || request.userId || 'current_chat',
    'ready',
    'Return through the current ChatGPT response channel.'
  );
}

for (const item of telegram) {
  const chatId = item?.chatId || request.telegramChatId || request.userId;

  if (!item?.text) {
    rejected.push({ channel: 'telegram', item, reason: 'missing_text' });
    continue;
  }

  if (!chatId) {
    rejected.push({ channel: 'telegram', item, reason: 'missing_chat_id' });
    continue;
  }

  pushQueue(
    'telegram',
    { ...item, chatId },
    String(chatId),
    dispatchEnabled ? 'ready_to_send' : 'preview_only',
    dispatchEnabled
      ? 'Telegram connector may send this payload.'
      : 'Dispatch is disabled during safe testing.'
  );
}

for (const item of whatsapp) {
  const to = item?.to || request.whatsappNumber;

  if (!item?.text) {
    rejected.push({ channel: 'whatsapp', item, reason: 'missing_text' });
    continue;
  }

  if (!to) {
    rejected.push({ channel: 'whatsapp', item, reason: 'missing_phone_number' });
    continue;
  }

  pushQueue(
    'whatsapp',
    { ...item, to },
    String(to),
    dispatchEnabled ? 'ready_to_send' : 'preview_only',
    dispatchEnabled
      ? 'WhatsApp connector may send this payload.'
      : 'Dispatch is disabled during safe testing.'
  );
}

const chatgptResponses = dispatchQueue
  .filter(item => item.channel === 'chatgpt')
  .map(item => ({
    dispatchId: item.dispatchId,
    title: item.payload.title || '',
    message: item.payload.message,
    type: item.type
  }));

const telegramQueue = dispatchQueue
  .filter(item => item.channel === 'telegram')
  .map(item => ({
    dispatchId: item.dispatchId,
    chatId: item.destination,
    text: item.payload.text,
    parseMode: item.payload.parseMode || 'Markdown',
    buttons: item.payload.buttons || [],
    scheduledFor: item.payload.scheduledFor || null,
    approvalId: item.payload.approvalId || null,
    relatedActionId: item.payload.relatedActionId || null,
    status: item.status
  }));

const whatsappQueue = dispatchQueue
  .filter(item => item.channel === 'whatsapp')
  .map(item => ({
    dispatchId: item.dispatchId,
    to: item.destination,
    text: item.payload.text,
    scheduledFor: item.payload.scheduledFor || null,
    relatedActionId: item.payload.relatedActionId || null,
    status: item.status
  }));

const summary = {
  inputChatGPTCount: chatgpt.length,
  inputTelegramCount: telegram.length,
  inputWhatsAppCount: whatsapp.length,
  queuedCount: dispatchQueue.length,
  rejectedCount: rejected.length,
  chatgptReadyCount: chatgptResponses.length,
  telegramReadyCount: telegramQueue.length,
  whatsappReadyCount: whatsappQueue.length,
  dispatchEnabled
};

return [{
  json: {
    success: true,
    result: {
      summary,
      dispatchQueue,
      channelDispatch: {
        chatgptResponses,
        telegramQueue,
        whatsappQueue
      },
      rejected
    },
    memoryUpdates: dispatchQueue.map(item => ({
      type: 'dispatch_history',
      operation: 'append',
      payload: {
        dispatchId: item.dispatchId,
        notificationId: item.notificationId,
        channel: item.channel,
        destination: item.destination,
        status: item.status,
        createdAt: item.createdAt
      }
    })),
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Channel Dispatcher',
      level: rejected.length ? 'warning' : 'info',
      correlationId: metadata.correlationId || '',
      message: `Prepared ${dispatchQueue.length} channel dispatch items.`,
      details: summary
    }],
    nextAction: {
      type: dispatchEnabled ? 'send_via_channel_connectors' : 'review_dispatch_preview',
      targetWorkflow: dispatchEnabled
        ? 'Concierge OS - Channel Connectors'
        : null
    },
    error: null
  }
}];
